if(NS.UI){const head=NS.UI.prototype.renderHeader,map=NS.UI.prototype.renderMap,content=NS.UI.prototype.renderVillageContent;NS.UI.prototype.renderHeader=function(){head.call(this);document.title='Village Observer V0.32D1';const b=document.getElementById('versionBadge');if(b)b.innerHTML='Village Observer · <strong>V0.32D1</strong>';const st=this.q('runtimeStatus');if(st)st.textContent='✓ V0.32D1 D 안정화 · 야전 Formation 실분리/이동 · 통계/지도/행정청/가격/CSV 수정';};NS.UI.prototype.renderMap=function(){map.call(this);drawGarrison32D1(this);};NS.UI.prototype.renderVillageContent=function(){content.call(this);const v=this.world.selectedNation,root=this.q('villageContent');if(!v||!root)return;if(this.sub==='military'){const m=d1Military(v,this.world),host=root.querySelector('.v32d-formations');if(host&&!host.querySelector('.v32d1-split'))host.insertAdjacentHTML('afterbegin',`<div class="small muted v32d1-split" style="margin-bottom:7px">D1 실병력 분리 · ■ Garrison ${m.garrisonManpower32D1}명 / ▲ 야전 Formation ${m.fieldManpower32D1}명 · 목표 변경 ${m.formationTargetsChanged32D1}회</div>`);}if(this.sub==='economy'){const a=d1AdminDiag(v),host=root.querySelector('.v32d-admin-box');if(host&&!host.querySelector('.v32d1-admin-diag'))host.insertAdjacentHTML('beforeend',`<div class="small muted v32d1-admin-diag" style="margin-top:7px">행정청 후보 #${a.adminOfficeTarget32D1||'-'} · 안정 ${a.adminOfficeStableYears32D1.toFixed(1)}년 · 차단 ${a.adminOfficeBlocker32D1} · 공간정비 ${a.adminOfficeSpacePreps32D1}회</div>`);}};}

