if(Array.isArray(NS.PATCH_NOTES)&&!NS.PATCH_NOTES.some(x=>x.version==='V0.32D1'))NS.PATCH_NOTES.unshift({version:'V0.32D1',date:'2026-09-26',title:'D 안정화 · 야전 Formation 실분리와 관측 버그 수정',summary:'122년 자연주행에서 드러난 “표시는 되지만 실제 행동은 발화하지 않는” D 기능을 수정합니다. 전투를 추가하지 않고 D에서 약속한 Formation 이동·행정청·통계·지도 표현을 실제 자연주행에서 검증 가능한 상태로 완성합니다.',sections:[['핵심 변화',['현역 Person을 수도의 고정 Garrison Cohort와 별도의 야전 Field Cohort로 실제 분할합니다. 한 Person이 두 군사 위치에 중복 소속되지 않습니다.','현역 2명 이상인 국가는 최소 1명을 주둔군으로 남기고 일부 현역을 야전대로 편성합니다. 야전 Cohort만 Formation으로 지도 위를 이동합니다.','야전 Formation은 국경·행정 중심·철산업·도로·개척 전선을 평가하며, 자국 영토가 충분하면 수도가 아닌 전략 타일로 실제 배치됩니다.']],['버그 수정',['세계 통계의 인구·영토 타일·국가 평균 기술 수·행정 중심지 수가 x.global.global을 잘못 읽어 빈 그래프가 되던 문제를 수정했습니다.','지도 표시 선택기가 값만 바꾸고 실제 최종 renderer는 30% 영토 tint로 고정하던 문제를 수정했습니다. 국가 중심은 약 40%, 균형은 약 30%, 지형 중심은 약 9% tint를 사용합니다.','Formation 이동 로그가 같은 분기 안에서 합쳐질 때 실제 이동 누적 수가 증가하지 않던 계수 문제를 수정했습니다.','멸망 국가의 Survival 상태가 세계 Survival 국가 수에 남는 현상을 활성 국가 기준으로 정리합니다.']],['행정권·행정청',['행정 중심지가 인접 타일로 소폭 이동해도 같은 A/B/C 행정권으로 이어지도록 중심지 연속성을 추가했습니다. 이 경우 6년 안정 기간도 유지됩니다.','6년이 지난 비수도 행정 중심지에 공간이 부족하면 행정청을 포기하지 않고 해당 중심지의 토지 정비를 우선 시도합니다.','행정청 후보 타일·안정 기간·차단 사유(PROJECT_CAPACITY, SPACE, SURVIVAL_MODE 등)를 국가 경제 화면과 telemetry에 표시합니다.']],['가격·관측',['신규 세계의 목재 0.35, 석재 0.49, 철광석 0.90을 1년 차 기준가격으로 유지하고 2~3년에 걸쳐 실제 수요·공급 가격으로 점진 전환합니다. 시작 직후 가격이 기준값을 즉시 덮어쓰는 현상을 완화합니다.','V0.32D에서 JSON에만 있던 Formation·행정권·식량 접근·로그 압축 필드를 Snapshot CSV에도 추가합니다.']],['개발자 로그',['INTERNAL_LOGISTICS·재정/슬롯 차단 상세은 최근 2년, 식량 접근 차단·긴급 수송 상세은 최근 3년을 유지하고 그 이전은 연간 LOG_SUMMARY32D로 압축합니다.','Formation 이동 로그는 분기별 집계 형식을 유지하면서 실제 이동 칸 수는 정확하게 누적합니다.']]]});

(function(){const KEY='village-observer-v0-32d1',fallback=['village-observer-v0-32d','village-observer-v0-32c2','village-observer-v0-32c1a','village-observer-v0-32c1','village-observer-v0-32c','village-observer-v0-32b','village-observer-v0-32a','village-observer-v0-31i','village-observer-v0-31h','village-observer-v0-31g','village-observer-v0-31f','village-observer-v0-31a','village-observer-v0-31'];function dl(name,text,type='application/json'){const blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}NS.SaveSystem={save(w){localStorage.setItem(KEY,JSON.stringify(w.serialize()));},load(){let r=localStorage.getItem(KEY);for(const k of fallback)if(!r)r=localStorage.getItem(k);return r?NS.World.from(JSON.parse(r)):null;},export(w){dl(`village-observer-v032D1-save-${w.year}y.json`,JSON.stringify(w.serialize()));},exportDevJSON(w){NS.V032D?.compactLogs?.(w.telemetry,w,true);dl(`village-observer-v032D1-devlog-${w.telemetry.sessionId}.json`,JSON.stringify(w.telemetry.toJSON(w)));},exportDevCSV(w){dl(`village-observer-v032D1-snapshots-${w.telemetry.sessionId}.csv`,'\ufeff'+w.telemetry.snapshotsCSV(),'text/csv;charset=utf-8');},async import(file){return NS.World.from(JSON.parse(await file.text()));},async importMap(file){return attach(NS.V019.worldFromMapData(JSON.parse(await file.text())));}};})();
